        emon.Port.CellsDrop(ac, wi * GuStride);
        return 0;
    }
    internal static int LcBestPiece(emon.Port.Cells it, emon.Port.Cells io, int s, int e, int ax0, int ax1, emon.Port.Cells tm) {
        // The widest part of [ax0, ax1] that no item of the row io[s..e) (sorted by x) touches: its ends are
        // put in tm[0] and tm[1], its width answered (0 when none).
        int lo = ax0;
        int bw = 0;
        int b0 = ax0;
        int b1 = ax0;
        int k = s;
        while (k < e) {
            int ix = emon.Port.CellsAt(io, k);
            int x0 = emon.Port.CellsAt(it, ix * ItStride);
            int x1 = emon.Port.CellsAt(it, (ix * ItStride) + 1);
            if ((x0 < ax1) && (x1 > ax0)) {
                if ((LcMin(x0, ax1) - lo) > bw) {
                    bw = LcMin(x0, ax1) - lo;
                    b0 = lo;
                    b1 = LcMin(x0, ax1);
                }
                lo = LcMax(lo, x1);
            }
            k += 1;
        }
        if ((ax1 - lo) > bw) {
            bw = ax1 - lo;
            b0 = lo;
            b1 = ax1;
        }
        emon.Port.CellsSet(tm, 0, b0);
        emon.Port.CellsSet(tm, 1, b1);
        return bw;
    }
    internal static int LcCountLeft(emon.Port.Cells it, emon.Port.Cells io, int s, int e, int x, int gmin) {
        // The words of the run of ink that ends at or left of x: the items whose right edge is at or left of
        // x, from the one nearest back while no gap of `gmin` or more parts two. (A table's cell is a run of one
        // or two words; a column's line has many.)
        int k = s;
        int kl = -1;
        int n = 0;
        while (k < e) {
            if (emon.Port.CellsAt(it, (emon.Port.CellsAt(io, k) * ItStride) + 1) <= x) {
                kl = k;
            }
            k += 1;
        }
        if (kl < 0) {
            return 0;
        }
        n = 1;
        k = kl - 1;
        while (k >= s) {
            int a = emon.Port.CellsAt(io, k);
            int b = emon.Port.CellsAt(io, k + 1);
            if ((emon.Port.CellsAt(it, b * ItStride) - emon.Port.CellsAt(it, (a * ItStride) + 1)) >= gmin) {
                return n;
            }
            n += 1;
            k -= 1;
        }
        return n;
    }
    internal static int LcCountRight(emon.Port.Cells it, emon.Port.Cells io, int s, int e, int x, int gmin) {
        // The words of the run of ink that starts at or right of x, as `lc-count-left`.
        int k = e;
        int kr = -1;
        int n = 0;
        k = e - 1;
        while (k >= s) {
            if (emon.Port.CellsAt(it, emon.Port.CellsAt(io, k) * ItStride) >= x) {
                kr = k;
            }
            k -= 1;
        }
        if (kr < 0) {
            return 0;
        }
        n = 1;
        k = kr + 1;
        while (k < e) {
            int a = emon.Port.CellsAt(io, k - 1);
            int b = emon.Port.CellsAt(io, k);
            if ((emon.Port.CellsAt(it, b * ItStride) - emon.Port.CellsAt(it, (a * ItStride) + 1)) >= gmin) {
                return n;
            }
            n += 1;
            k += 1;
        }
        return n;
    }
    internal static int LcRow(emon.Port.Cells it, emon.Port.Cells io, int s, int e, int size, int ry0, int ry1, int hasclass, emon.Port.Cells ac, emon.Port.Cells gu, emon.Port.Cells tm, emon.Port.Cells rw) {
        // One row of ink, its items io[s..e) sorted by x. Every active interval is cut down by the ink in it:
        // it goes on where a part `gutter-min` wide is left, else it ends. Where the row has type of body size
        // it also counts as a row of the interval, and the gaps between two runs of ink at least `gutter-min`
        // wide that no active interval touches begin new ones.
        int reach = emon.Port.CellsAt(it, (emon.Port.CellsAt(io, s) * ItStride) + 1);
        int k = s + 1;
        int med = 0;
        int gmin = 0;
        int a = 0;
        int wi = 0;
        int c = 0;
        int bw = 0;
        int lc = 0;
        int rc = 0;
        int hit = 0;
        int nrun = 1;
        int cur = 1;
        int maxrun = 1;
        int tab = 0;
        int rx0 = 0;
        int rx1 = 0;
        emon.Port.CellsDrop(rw, 0);
        while (k < e) {
            int ix = emon.Port.CellsAt(io, k);
            int gap = emon.Port.CellsAt(it, ix * ItStride) - reach;
            emon.Port.CellsPush(rw, LcMax(gap, 0));
            reach = LcMax(reach, emon.Port.CellsAt(it, (ix * ItStride) + 1));
            k += 1;
        }
        LcSortNums(rw);
        if (emon.Port.CellsLen(rw) >= 3) {
            med = emon.Port.CellsAt(rw, (emon.Port.CellsLen(rw) - 1) / 2);
        }
        gmin = LcMax((size * LcGutNum) / LcGutDen, (med * 3) / 2);
        reach = emon.Port.CellsAt(it, (emon.Port.CellsAt(io, s) * ItStride) + 1);
        k = s + 1;
        while (k < e) {
            int ix = emon.Port.CellsAt(io, k);
            int x0 = emon.Port.CellsAt(it, ix * ItStride);
            if ((x0 - reach) >= (size * 3)) {
                nrun += 1;
                cur = 1;
            } else {
                cur += 1;
                if (cur > maxrun) {
                    maxrun = cur;
                }
            }
            reach = LcMax(reach, emon.Port.CellsAt(it, (ix * ItStride) + 1));
            k += 1;
        }
        if ((nrun >= LcTableRuns) && (maxrun <= LcTableWords)) {
            tab = 1;
            rx0 = emon.Port.CellsAt(it, emon.Port.CellsAt(io, s) * ItStride);
            rx1 = reach;
            emon.Port.CellsPush(gu, rx0);
            emon.Port.CellsPush(gu, rx1);
            emon.Port.CellsPush(gu, ry0);
            emon.Port.CellsPush(gu, ry1);
            emon.Port.CellsPush(gu, 0);
            emon.Port.CellsPush(gu, 0);
            emon.Port.CellsPush(gu, 0);
            emon.Port.CellsPush(gu, 0);
            emon.Port.CellsPush(gu, 0);
            emon.Port.CellsPush(gu, 2);
            emon.Port.CellsPush(gu, 0);
            emon.Port.CellsPush(gu, 0);
            LcCloseWithin(gu, ac, rx0, rx1);
        }
        int na = emon.Port.CellsLen(ac) / GuStride;
        a = 0;
        while (a < na) {
            int ab = a * GuStride;
            bw = LcBestPiece(it, io, s, e, emon.Port.CellsAt(ac, ab), emon.Port.CellsAt(ac, ab + 1), tm);
            if (bw >= ((size * LcGutNum) / LcGutDen)) {
                int p0 = emon.Port.CellsAt(tm, 0);
                int p1 = emon.Port.CellsAt(tm, 1);
                emon.Port.CellsSet(ac, ab, p0);
                emon.Port.CellsSet(ac, ab + 1, p1);
                if (hasclass == 1) {
                    lc = LcCountLeft(it, io, s, e, p0, gmin);
                    rc = LcCountRight(it, io, s, e, p1, gmin);
                    int one = LcOneSided(lc, rc);
                    int oBot = emon.Port.CellsAt(ac, ab + GuBot);
                    int oRows = emon.Port.CellsAt(ac, ab + GuRows);
                    int oLr = emon.Port.CellsAt(ac, ab + GuLrows);
                    int oLs = emon.Port.CellsAt(ac, ab + GuLsum);
                    int oRr = emon.Port.CellsAt(ac, ab + GuRrows);
                    int oRs = emon.Port.CellsAt(ac, ab + GuRsum);
                    emon.Port.CellsSet(ac, ab + GuPbot, oBot);
                    emon.Port.CellsSet(ac, ab + GuOne, one);
                    emon.Port.CellsSet(ac, ab + GuBot, LcMax(oBot, ry1));
                    emon.Port.CellsSet(ac, ab + GuRows, oRows + 1);
                    if (lc > 0) {
                        emon.Port.CellsSet(ac, ab + GuLrows, oLr + 1);
                        emon.Port.CellsSet(ac, ab + GuLsum, oLs + lc);
                    }
                    if (rc > 0) {
                        emon.Port.CellsSet(ac, ab + GuRrows, oRr + 1);
                        emon.Port.CellsSet(ac, ab + GuRsum, oRs + rc);
                    }
                }
                if (wi != a) {
                    c = 0;
                    while (c < GuStride) {
                        int v = emon.Port.CellsAt(ac, ab + c);
                        emon.Port.CellsSet(ac, (wi * GuStride) + c, v);
                        c += 1;
                    }
                }
                wi += 1;
            } else {
                LcCloseTrim(gu, ac, a, ry0, size);
            }
            a += 1;
        }
        emon.Port.CellsDrop(ac, wi * GuStride);
        if ((hasclass == 1) && (tab == 0)) {
            reach = emon.Port.CellsAt(it, (emon.Port.CellsAt(io, s) * ItStride) + 1);
            k = s + 1;
            while (k < e) {
                int ix = emon.Port.CellsAt(io, k);
                int x0 = emon.Port.CellsAt(it, ix * ItStride);
                if ((x0 - reach) >= gmin) {
                    hit = 0;
                    a = 0;
                    while (a < (emon.Port.CellsLen(ac) / GuStride)) {
                        if ((emon.Port.CellsAt(ac, a * GuStride) < x0) && (emon.Port.CellsAt(ac, (a * GuStride) + 1) > reach)) {
                            hit = 1;
                        }
                        a += 1;
                    }
                    if (hit == 0) {
                        emon.Port.CellsPush(ac, reach);
                        emon.Port.CellsPush(ac, x0);
                        emon.Port.CellsPush(ac, ry0);
                        emon.Port.CellsPush(ac, ry1);
                        emon.Port.CellsPush(ac, 1);
                        emon.Port.CellsPush(ac, 1);
                        emon.Port.CellsPush(ac, 1);
                        emon.Port.CellsPush(ac, LcCountLeft(it, io, s, e, reach, gmin));
                        emon.Port.CellsPush(ac, LcCountRight(it, io, s, e, x0, gmin));
                        emon.Port.CellsPush(ac, 0);
                        emon.Port.CellsPush(ac, ry0);
                        emon.Port.CellsPush(ac, 0);
                    }
                }
                reach = LcMax(reach, emon.Port.CellsAt(it, (ix * ItStride) + 1));
                k += 1;
            }
        }
        return 0;
    }
    internal static int LcSweep(emon.Port.Cells wd, emon.Port.Cells lt, emon.Port.Cells ls, int dom, emon.Port.Cells it, emon.Port.Cells io, emon.Port.Cells rw, emon.Port.Cells gu, emon.Port.Cells ac, emon.Port.Cells tm) {
        // The gutters of the words of the lines in `ls`: ink rows top to bottom (SPEC 10.1.1 step 1). A row
        // is the words whose baselines are within half a size of the first's.
        int s = 0;
        int e = 0;
        int size = 0;
        int ry0 = 0;
        int ry1 = 0;
        int hasclass = 0;
        int prevq = -1000000000;
        int k = 0;
        emon.Port.CellsDrop(gu, 0);
        emon.Port.CellsDrop(ac, 0);
        emon.Port.CellsDrop(tm, 0);
        emon.Port.CellsPush(tm, 0);
        emon.Port.CellsPush(tm, 0);
        LcItems(wd, lt, ls, it, io);
        int m = emon.Port.CellsLen(io);
        if (m == 0) {
            return 0;
        }
        LcSortItems(it, io, 0, m, 0);
        while (s < m) {
            int i0 = emon.Port.CellsAt(io, s);
            int y0 = emon.Port.CellsAt(it, (i0 * ItStride) + 2);
            int sz0 = emon.Port.CellsAt(it, (i0 * ItStride) + 3);
            e = s + 1;
            while ((e < m) && ((emon.Port.CellsAt(it, (emon.Port.CellsAt(io, e) * ItStride) + 2) - y0) <= LcMin(sz0, emon.Port.CellsAt(it, (emon.Port.CellsAt(io, e) * ItStride) + 3)))) {
                e += 1;
            }
            LcSortItems(it, io, s, e, 1);
            size = 0;
            ry0 = 1000000000;
            ry1 = -1000000000;
            hasclass = 0;
            k = s;
            while (k < e) {
                int ix = emon.Port.CellsAt(io, k);
                int sz = emon.Port.CellsAt(it, (ix * ItStride) + 3);
                size = LcMax(size, sz);
                if (LcIsClass(sz, dom)) {
                    hasclass = 1;
                }
                ry0 = LcMin(ry0, emon.Port.CellsAt(it, (ix * ItStride) + 5));
                ry1 = LcMax(ry1, emon.Port.CellsAt(it, (ix * ItStride) + 6));
                k += 1;
            }
            if ((hasclass == 1) && ((ry0 - prevq) > (LcHole * dom))) {
                LcCloseAll(gu, ac);
            }
            LcRow(it, io, s, e, LcMin(size, dom), ry0, ry1, hasclass, ac, gu, tm, rw);
            if (hasclass == 1) {
                prevq = LcMax(prevq, ry1);
            }
            s = e;
        }
        LcCloseAll(gu, ac);
        return emon.Port.CellsLen(gu) / GuStride;
    }
    internal static int LcMerge(emon.Port.Cells gu, int dom) {
        // Gutters of one column gap that the sweep saw in pieces (a figure in one column, a heading) are one:
        // their x-intervals overlap by half of the narrower and their extents are within `hole` sizes.
        int n = emon.Port.CellsLen(gu) / GuStride;
        int i = 0;
        int j = 0;
        int f = 0;
        int wi = 0;
        while (i < n) {
            j = i + 1;
            while (j < n) {
                int ib = i * GuStride;
                int jb = j * GuStride;
                if ((emon.Port.CellsAt(gu, ib + GuFlag) == 0) && (emon.Port.CellsAt(gu, jb + GuFlag) == 0)) {
                    int ix0 = emon.Port.CellsAt(gu, ib);
                    int ix1 = emon.Port.CellsAt(gu, ib + 1);
                    int jx0 = emon.Port.CellsAt(gu, jb);
                    int jx1 = emon.Port.CellsAt(gu, jb + 1);
                    int ox = LcMin(ix1, jx1) - LcMax(ix0, jx0);
                    int wmin = LcMin(ix1 - ix0, jx1 - jx0);
                    int itop = emon.Port.CellsAt(gu, ib + GuTop);
                    int ibot = emon.Port.CellsAt(gu, ib + GuBot);
                    int jtop = emon.Port.CellsAt(gu, jb + GuTop);
                    int jbot = emon.Port.CellsAt(gu, jb + GuBot);
                    if ((ox > 0) && ((ox * 2) >= wmin) && (jtop <= (ibot + (LcHole * dom))) && (itop <= (jbot + (LcHole * dom)))) {
                        emon.Port.CellsSet(gu, ib, LcMax(ix0, jx0));
                        emon.Port.CellsSet(gu, ib + 1, LcMin(ix1, jx1));
                        emon.Port.CellsSet(gu, ib + GuTop, LcMin(itop, jtop));
                        emon.Port.CellsSet(gu, ib + GuBot, LcMax(ibot, jbot));
                        f = 4;
                        while (f < 9) {
                            int sum = emon.Port.CellsAt(gu, ib + f) + emon.Port.CellsAt(gu, jb + f);
                            emon.Port.CellsSet(gu, ib + f, sum);
                            f += 1;
                        }
                        emon.Port.CellsSet(gu, jb + GuFlag, 1);
                    }
                }
                j += 1;
            }
            i += 1;
        }
        i = 0;
        while (i < n) {
            if (emon.Port.CellsAt(gu, (i * GuStride) + GuFlag) != 1) {
                if (wi != i) {
                    f = 0;
                    while (f < GuStride) {
                        int v = emon.Port.CellsAt(gu, (i * GuStride) + f);
                        emon.Port.CellsSet(gu, (wi * GuStride) + f, v);
                        f += 1;
                    }
                }
                wi += 1;
            }
            i += 1;
        }
        emon.Port.CellsDrop(gu, wi * GuStride);
        return wi;
    }
    internal static int LcSortGu(emon.Port.Cells gu) {
        // Insertion sort of the gutters by their left edge.
        int n = emon.Port.CellsLen(gu) / GuStride;
        int i = 1;
        int j = 0;
        int f = 0;
        int more = 1;
        while (i < n) {
            j = i;
            more = 1;
            while ((j > 0) && (more == 1)) {
                if (emon.Port.CellsAt(gu, j * GuStride) < emon.Port.CellsAt(gu, (j - 1) * GuStride)) {
                    f = 0;
                    while (f < GuStride) {
                        int a = emon.Port.CellsAt(gu, (j * GuStride) + f);
                        int b = emon.Port.CellsAt(gu, ((j - 1) * GuStride) + f);
                        emon.Port.CellsSet(gu, (j * GuStride) + f, b);
                        emon.Port.CellsSet(gu, ((j - 1) * GuStride) + f, a);
                        f += 1;
                    }
                    j -= 1;
                } else {
                    more = 0;
                }
            }
            i += 1;
        }
        return 0;
    }
    internal static int LcSplitAll(emon.Port.Cells wd, emon.Port.Cells lt, emon.Port.Cells ls, emon.Port.Cells gu) {
        // SPLIT (step 2): every line inside a gutter's extent whose words are on both sides of it.
        int ng = emon.Port.CellsLen(gu) / GuStride;
        int g = 0;
        int i = 0;
        while (g < ng) {
            int gb = g * GuStride;
            int gx0 = emon.Port.CellsAt(gu, gb);
            int gx1 = emon.Port.CellsAt(gu, gb + 1);
            int top2 = 2 * emon.Port.CellsAt(gu, gb + GuTop);
            int bot2 = 2 * emon.Port.CellsAt(gu, gb + GuBot);
            i = 0;
            while ((i < emon.Port.CellsLen(ls)) && (emon.Port.CellsAt(gu, gb + GuFlag) == 0)) {
                int l = emon.Port.CellsAt(ls, i);
                int ym = LcYm2(lt, l);
                if ((ym >= top2) && (ym <= bot2)) {
                    LcSplit(wd, lt, ls, l, gx0, gx1);
                }
                i += 1;
            }
            g += 1;
        }
        return 0;
    }
    internal static bool LcCrosses(emon.Port.Cells lt, int l, int gx0, int gx1) {
        return (Evidence.LnGet(lt, l, Evidence.LhX0()) < gx1) && (Evidence.LnGet(lt, l, Evidence.LhX1()) > gx0);
    }
    internal static int LcAbove(emon.Port.Cells lt, emon.Port.Cells ls, int l) {
        // The line nearest above line l (wholly above it, to a quarter of its height): the one with the lowest
        // bottom. -1 for none.
        int n = emon.Port.CellsLen(ls);
        int top = Evidence.LnGet(lt, l, Evidence.LhY0()) + ((Evidence.LnGet(lt, l, Evidence.LhY1()) - Evidence.LnGet(lt, l, Evidence.LhY0())) / 4);
        int best = -1;
        int by = -1000000000;
        int i = 0;
        while (i < n) {
            int m = emon.Port.CellsAt(ls, i);
            int y1 = Evidence.LnGet(lt, m, Evidence.LhY1());
            if ((y1 <= top) && (y1 > by)) {
                by = y1;
                best = m;
            }
            i += 1;
        }
        return best;
    }
    internal static int LcBelow(emon.Port.Cells lt, emon.Port.Cells ls, int l) {
        // The line nearest below line l (wholly below it, to a quarter of its height): the one with the highest
        // top. -1 for none.
        int n = emon.Port.CellsLen(ls);
        int bot = Evidence.LnGet(lt, l, Evidence.LhY1()) - ((Evidence.LnGet(lt, l, Evidence.LhY1()) - Evidence.LnGet(lt, l, Evidence.LhY0())) / 4);
        int best = -1;
        int by = 1000000000;
        int i = 0;
        while (i < n) {
            int m = emon.Port.CellsAt(ls, i);
            int y0 = Evidence.LnGet(lt, m, Evidence.LhY0());
            if ((y0 >= bot) && (y0 < by)) {
                by = y0;
                best = m;
            }
            i += 1;
        }
        return best;
    }
    internal static bool LcInTable(emon.Port.Cells lt, emon.Port.Cells gu, int l, int gx0, int gx1) {
        // Does the line lie in a table row that spans the gutter (the marks of `lc-row`, flag 2): a spanning element.
        int ng = emon.Port.CellsLen(gu) / GuStride;
        int g = 0;
        while (g < ng) {
            int gb = g * GuStride;
            if ((emon.Port.CellsAt(gu, gb + GuFlag) == 2) && (emon.Port.CellsAt(gu, gb) < gx0) && (gx1 < emon.Port.CellsAt(gu, gb + 1)) && (Evidence.LnGet(lt, l, Evidence.LhY0()) < emon.Port.CellsAt(gu, gb + GuBot)) && (Evidence.LnGet(lt, l, Evidence.LhY1()) > emon.Port.CellsAt(gu, gb + GuTop))) {
                return 1 == 1;
            }
            g += 1;
        }
        return 0 == 1;
    }
    internal static int LcExtendUp(emon.Port.Cells wd, emon.Port.Cells lt, emon.Port.Cells ls, emon.Port.Cells gu, int dom) {
        // A gutter's extent goes up through the lines of body size that lie on one side of it (a heading or
        // the first lines of one column before the other starts), until a line crosses it or a gap of `hole`
        // sizes; not through the last line of a paragraph that spans the gutter, which is the line that has one
        // close above it that crosses it. (Down, the sweep already carried it.)
        int ng = emon.Port.CellsLen(gu) / GuStride;
        int n = emon.Port.CellsLen(ls);
        int g = 0;
        int i = 0;
        int done = 0;
        int cur = 0;
        while (g < ng) {
            int gb = g * GuStride;
            int gx0 = emon.Port.CellsAt(gu, gb);
            int gx1 = emon.Port.CellsAt(gu, gb + 1);
            int top0 = emon.Port.CellsAt(gu, gb + GuTop);
            cur = top0;
            done = 0;
            if (emon.Port.CellsAt(gu, gb + GuFlag) != 0) {
                done = 1;
            }
            i = n - 1;
            while ((i >= 0) && (done == 0)) {
                int l = emon.Port.CellsAt(ls, i);
                if (LcYm2(lt, l) < (2 * top0)) {
                    if (LcCrosses(lt, l, gx0, gx1) || LcInTable(lt, gu, l, gx0, gx1)) {
                        done = 1;
                    } else if (LcIsClass(LcSize(wd, lt, l), dom)) {
                        if ((cur - Evidence.LnGet(lt, l, Evidence.LhY1())) > (LcHole * dom)) {
                            done = 1;
                        } else {
                            int a = LcAbove(lt, ls, l);
                            if ((a >= 0) && LcCrosses(lt, a, gx0, gx1) && (((Evidence.LnGet(lt, l, Evidence.LhY0()) - Evidence.LnGet(lt, a, Evidence.LhY1())) * LcTightDen) <= (dom * LcTightNum))) {
                                done = 1;
                            } else {
                                cur = LcMin(cur, Evidence.LnGet(lt, l, Evidence.LhY0()));
                            }
                        }
                    }
                }
                i -= 1;
            }
            emon.Port.CellsSet(gu, gb + GuTop, cur);
            g += 1;
        }
        return 0;
    }
    internal const int PrXmin = 8;
    internal const int PrXmax = 9;
    internal const int PrY2min = 10;
    internal const int PrY2max = 11;
    internal const int PrY1max = 12;
    internal static int LcStats(emon.Port.Cells lt, emon.Port.Cells ls, int a, int b, emon.Port.Cells pr) {
        // The region ls[a..b): the extent of its lines' boxes (x) and of their middles (y, times 2).
        int xmin = 1000000000;
        int xmax = -1000000000;
        int ymin = 1000000000;
        int ymax = -1000000000;
        int bmax = -1000000000;
        int i = a;
        while (i < b) {
            int l = emon.Port.CellsAt(ls, i);
            int ym = LcYm2(lt, l);
            xmin = LcMin(xmin, Evidence.LnGet(lt, l, Evidence.LhX0()));
            xmax = LcMax(xmax, Evidence.LnGet(lt, l, Evidence.LhX1()));
            bmax = LcMax(bmax, Evidence.LnGet(lt, l, Evidence.LhY1()));
            ymin = LcMin(ymin, ym);
            ymax = LcMax(ymax, ym);
            i += 1;
        }
        emon.Port.CellsSet(pr, PrY1max, bmax);
        emon.Port.CellsSet(pr, PrXmin, xmin);
        emon.Port.CellsSet(pr, PrXmax, xmax);
        emon.Port.CellsSet(pr, PrY2min, ymin);
        emon.Port.CellsSet(pr, PrY2max, ymax);
        return 0;
    }
    internal static int LcCountSide(emon.Port.Cells lt, emon.Port.Cells ls, int a, int b, int gx0, int gx1, int side) {
        // The lines of the region wholly left (side 0) or right (side 1) of the gutter.
        int i = a;
        int n = 0;
        while (i < b) {
            int l = emon.Port.CellsAt(ls, i);
            if (side == 0) {
                if (Evidence.LnGet(lt, l, Evidence.LhX1()) <= gx0) {
                    n += 1;
                }
            } else if (Evidence.LnGet(lt, l, Evidence.LhX0()) >= gx1) {
                n += 1;
            }
            i += 1;
        }
        return n;
    }
    internal static int LcVcut(emon.Port.Cells lt, emon.Port.Cells ls, emon.Port.Cells gu, int a, int b, emon.Port.Cells pr) {
        // A gutter whose extent covers every line of the region and that has lines on both sides: its index, or -1.
        int ng = emon.Port.CellsLen(gu) / GuStride;
        int xmin = emon.Port.CellsAt(pr, PrXmin);
        int xmax = emon.Port.CellsAt(pr, PrXmax);
        int ymin = emon.Port.CellsAt(pr, PrY2min);
        int ymax = emon.Port.CellsAt(pr, PrY2max);
        int g = 0;
        while (g < ng) {
            int gb = g * GuStride;
            int gx0 = emon.Port.CellsAt(gu, gb);
            int gx1 = emon.Port.CellsAt(gu, gb + 1);
            if ((xmin < gx0) && (gx1 < xmax) && (emon.Port.CellsAt(gu, gb + GuFlag) == 0) && ((2 * emon.Port.CellsAt(gu, gb + GuTop)) <= ymin) && ((2 * emon.Port.CellsAt(gu, gb + GuBot)) >= ymax)) {
                if ((LcCountSide(lt, ls, a, b, gx0, gx1, 0) > 0) && (LcCountSide(lt, ls, a, b, gx0, gx1, 1) > 0)) {
                    return g;
                }
            }
            g += 1;
        }
        return -1;
    }
    internal static bool LcRelevant(emon.Port.Cells lt, emon.Port.Cells ls, emon.Port.Cells gu, int g, int a, int b, emon.Port.Cells pr) {
        // Does gutter g divide the region: its x-interval inside the region's lines, lines wholly on each side.
        int gb = g * GuStride;
        int gx0 = emon.Port.CellsAt(gu, gb);
        int gx1 = emon.Port.CellsAt(gu, gb + 1);
        if (emon.Port.CellsAt(gu, gb + GuFlag) != 0) {
            return 0 == 1;
        }
        if (!((emon.Port.CellsAt(pr, PrXmin) < gx0) && (gx1 < emon.Port.CellsAt(pr, PrXmax)))) {
            return 0 == 1;
        }
        return (LcCountSide(lt, ls, a, b, gx0, gx1, 0) > 0) && (LcCountSide(lt, ls, a, b, gx0, gx1, 1) > 0);
    }
    internal static bool LcInsideOther(emon.Port.Cells lt, emon.Port.Cells ls, emon.Port.Cells gu, int g, int a, int b, emon.Port.Cells pr, int p) {
        // Is y strictly inside the extent of another gutter that divides the region: its columns go on across
        // it, so it cannot be a cut (the cut is made between the columns of the other gutters, not through them).
        int ng = emon.Port.CellsLen(gu) / GuStride;
        int h = 0;
        while (h < ng) {
            if (h != g) {
                if (LcRelevant(lt, ls, gu, h, a, b, pr)) {
                    if ((emon.Port.CellsAt(gu, (h * GuStride) + GuTop) < p) && (p < emon.Port.CellsAt(gu, (h * GuStride) + GuBot))) {
                        return 1 == 1;
                    }
                }
            }
            h += 1;
        }
        return 0 == 1;
    }
    internal static int LcHcut(emon.Port.Cells lt, emon.Port.Cells ls, emon.Port.Cells gu, int a, int b, emon.Port.Cells pr) {
        // The first y at which to cut the region horizontally: the least top or bottom of the extent of a gutter
        // that divides it, strictly inside the region's lines, and not inside the extent of another gutter that
        // divides it. -1 for none.
        int ng = emon.Port.CellsLen(gu) / GuStride;
        int ymin = emon.Port.CellsAt(pr, PrY2min);
        int ymax = emon.Port.CellsAt(pr, PrY2max);
        int g = 0;
        int best = -1;
        while (g < ng) {
            int gb = g * GuStride;
            int top = emon.Port.CellsAt(gu, gb + GuTop);
            int bot = emon.Port.CellsAt(gu, gb + GuBot);
            if (LcRelevant(lt, ls, gu, g, a, b, pr)) {
                if (((2 * top) > ymin) && ((2 * top) <= ymax) && ((best < 0) || (top < best)) && !LcInsideOther(lt, ls, gu, g, a, b, pr, top)) {
                    best = top;
                }
                if (((2 * bot) > ymin) && ((2 * bot) <= ymax) && ((best < 0) || (bot < best)) && !LcInsideOther(lt, ls, gu, g, a, b, pr, bot)) {
                    best = bot;
                }
            }
            g += 1;
        }
        return best;
    }
    internal static int LcGapcut(emon.Port.Cells lt, emon.Port.Cells ls, emon.Port.Cells gu, int a, int b, emon.Port.Cells pr) {
        // A full-width gap: where the region's lines leave a gap of more than `hole` sizes with nothing across it,
        // the first such y (its middle), when a gutter divides the region (a region of one column is not cut
        // at every paragraph gap). -1 for none. A cut at a gap that lines up across balanced columns is never
        // made: only a gap wider than a paragraph gap is one (SPEC 10.1.1 step 4).
        int ng = emon.Port.CellsLen(gu) / GuStride;
        int thr = (LcGapNum * emon.Port.CellsAt(pr, PrDom)) / LcGapDen;
        int g = 0;
        int any = 0;
        int i = a + 1;
        int reach = 0;
        while (g < ng) {
            if (LcRelevant(lt, ls, gu, g, a, b, pr)) {
                any = 1;
            }
            g += 1;
        }
        if (any == 0) {
            return -1;
        }
        reach = Evidence.LnGet(lt, emon.Port.CellsAt(ls, a), Evidence.LhY1());
        while (i < b) {
            int l = emon.Port.CellsAt(ls, i);
            int y0 = Evidence.LnGet(lt, l, Evidence.LhY0());
            if ((y0 - reach) > thr) {
                return (reach + y0) / 2;
            }
            reach = LcMax(reach, Evidence.LnGet(lt, l, Evidence.LhY1()));
            i += 1;
        }
        return -1;
    }
    internal static int LcPartX(emon.Port.Cells lt, emon.Port.Cells ls, emon.Port.Cells tm, int a, int b, int gm2) {
        // Stable partition of the region: lines whose middle is left of the gutter's first. Answers how many.
        int i = a;
        int nl = 0;
        emon.Port.CellsDrop(tm, 0);
        while (i < b) {
            int l = emon.Port.CellsAt(ls, i);
            if ((Evidence.LnGet(lt, l, Evidence.LhX0()) + Evidence.LnGet(lt, l, Evidence.LhX1())) < gm2) {
                emon.Port.CellsPush(tm, l);
                nl += 1;
            }
            i += 1;
        }
        i = a;
        while (i < b) {
            int l = emon.Port.CellsAt(ls, i);
            if ((Evidence.LnGet(lt, l, Evidence.LhX0()) + Evidence.LnGet(lt, l, Evidence.LhX1())) >= gm2) {
                emon.Port.CellsPush(tm, l);
            }
            i += 1;
        }
        i = 0;
        while (i < (b - a)) {
            int v = emon.Port.CellsAt(tm, i);
            emon.Port.CellsSet(ls, a + i, v);
            i += 1;
        }
        return nl;
    }
    internal static int LcPartY(emon.Port.Cells lt, emon.Port.Cells ls, emon.Port.Cells tm, int a, int b, int p2) {
        // Stable partition of the region: lines whose middle is above y (2p2). Answers how many.
        int i = a;
        int na = 0;
        emon.Port.CellsDrop(tm, 0);
        while (i < b) {
            int l = emon.Port.CellsAt(ls, i);
            if (LcYm2(lt, l) < p2) {
                emon.Port.CellsPush(tm, l);
                na += 1;
            }
            i += 1;
        }
        i = a;
        while (i < b) {
            int l = emon.Port.CellsAt(ls, i);
            if (LcYm2(lt, l) >= p2) {
                emon.Port.CellsPush(tm, l);
            }
            i += 1;
        }
        i = 0;
        while (i < (b - a)) {
            int v = emon.Port.CellsAt(tm, i);
            emon.Port.CellsSet(ls, a + i, v);
            i += 1;
        }
        return na;
    }
    internal static int LcRef(int pbot, int y1) {
        // The bottom a column fragment is compared with: that of the region its vertical cuts came from (the
        // columns of one set end together), else its own.
        if (pbot > 0) {
            return pbot;
        }
        return y1;
    }
    internal static int LcLeaf(emon.Port.Cells lt, emon.Port.Cells ls, emon.Port.Cells lo, emon.Port.Cells cf, int a, int b, int band, int page, int pbot) {
        // A leaf: a column fragment. Its lines go to `lo` in rows; its row to `cf`.
        int x0 = 1000000000;
        int y0 = 1000000000;
        int x1 = -1000000000;
        int y1 = -1000000000;
        int i = a;
        int first = emon.Port.CellsLen(lo);
        LcSortLines(lt, ls, a, b);
        while (i < b) {
            int l = emon.Port.CellsAt(ls, i);
            x0 = LcMin(x0, Evidence.LnGet(lt, l, Evidence.LhX0()));
            y0 = LcMin(y0, Evidence.LnGet(lt, l, Evidence.LhY0()));
            x1 = LcMax(x1, Evidence.LnGet(lt, l, Evidence.LhX1()));
            y1 = LcMax(y1, Evidence.LnGet(lt, l, Evidence.LhY1()));
            emon.Port.CellsPush(lo, l);
            i += 1;
        }
        emon.Port.CellsPush(cf, page);
        emon.Port.CellsPush(cf, band);
        emon.Port.CellsPush(cf, 0);
        emon.Port.CellsPush(cf, Model.RlBody());
        emon.Port.CellsPush(cf, x0);
        emon.Port.CellsPush(cf, y0);
        emon.Port.CellsPush(cf, x1);
        emon.Port.CellsPush(cf, y1);
        emon.Port.CellsPush(cf, first);
        emon.Port.CellsPush(cf, b - a);
        emon.Port.CellsPush(cf, -1);
        emon.Port.CellsPush(cf, 0);
        emon.Port.CellsPush(cf, LcRef(pbot, y1));
        return 0;
    }
    internal static int LcNoteCut(emon.Port.Cells rw, emon.Port.Cells pr, int p) {
        // A horizontal cut at y = p, made on a region with the x-extent in `pr`: noted in `rw` (y x0 x1) for `lc-bands`.
        emon.Port.CellsPush(rw, p);
        emon.Port.CellsPush(rw, emon.Port.CellsAt(pr, PrXmin));
        emon.Port.CellsPush(rw, emon.Port.CellsAt(pr, PrXmax));
        return 0;
    }
    internal static int LcPush(emon.Port.Cells ac, int a, int b, int band, int pbot) {
        emon.Port.CellsPush(ac, a);
        emon.Port.CellsPush(ac, b);
        emon.Port.CellsPush(ac, band);
        emon.Port.CellsPush(ac, pbot);
        return 0;
    }
    internal static int LcRegion(emon.Port.Cells lt, emon.Port.Cells ls, emon.Port.Cells gu, emon.Port.Cells ac, emon.Port.Cells tm, emon.Port.Cells rw, emon.Port.Cells cf, emon.Port.Cells lo, emon.Port.Cells pr, int page, int a, int b, int band, int pbot) {
        // One region of the cut tree: cut it horizontally at the forced y or a full-width gap, else vertically, else
        // horizontally at the end of a gutter's extent, else it is a leaf. The halves go on the stack `ac` (4 cells: a b
        // band pbot), the one to read first last. `pbot` is the bottom of the region the vertical cuts above came from
        // (-1 for the whole page, 0 after a horizontal cut).
        int n = b - a;
        int done = 0;
        int na = 0;
        int g = -1;
        int p = -1;
        int @ref = 0;
        LcStats(lt, ls, a, b, pr);
        @ref = pbot;
        if ((pbot == -1) && (emon.Port.CellsAt(pr, PrForced) >= 0)) {
            na = LcPartY(lt, ls, tm, a, b, 2 * emon.Port.CellsAt(pr, PrForced));
            if ((na > 0) && (na < n)) {
                LcPush(ac, a + na, b, band + 1, 0);
                LcPush(ac, a, a + na, band, 0);
                LcNoteCut(rw, pr, emon.Port.CellsAt(pr, PrForced));
                done = 1;
            }
        }
        if (done == 0) {
            p = LcGapcut(lt, ls, gu, a, b, pr);
            if (p >= 0) {
                na = LcPartY(lt, ls, tm, a, b, 2 * p);
                if ((na > 0) && (na < n)) {
                    LcPush(ac, a + na, b, band + 1, 0);
                    LcPush(ac, a, a + na, band, 0);
                    LcNoteCut(rw, pr, p);
                    done = 1;
                }
            }
        }
        if (done == 0) {
            g = LcVcut(lt, ls, gu, a, b, pr);
            if (g >= 0) {
                int gb = g * GuStride;
                na = LcPartX(lt, ls, tm, a, b, emon.Port.CellsAt(gu, gb) + emon.Port.CellsAt(gu, gb + 1));
                if ((na > 0) && (na < n)) {
                    if (@ref <= 0) {
                        @ref = emon.Port.CellsAt(pr, PrY1max);
                    }
                    if (emon.Port.CellsAt(pr, PrRtl) == 1) {
                        LcPush(ac, a, a + na, band, @ref);
                        LcPush(ac, a + na, b, band, @ref);
                    } else {
                        LcPush(ac, a + na, b, band, @ref);
                        LcPush(ac, a, a + na, band, @ref);
                    }
                    done = 1;
                }
            }
        }
        if (done == 0) {
            p = LcHcut(lt, ls, gu, a, b, pr);
            if (p >= 0) {
                na = LcPartY(lt, ls, tm, a, b, 2 * p);
                if ((na > 0) && (na < n)) {
                    LcPush(ac, a + na, b, band + 1, 0);
                    LcPush(ac, a, a + na, band, 0);
                    LcNoteCut(rw, pr, p);
                    done = 1;
                }
            }
        }
        if (done == 0) {
            LcLeaf(lt, ls, lo, cf, a, b, band, page, pbot);
        }
        return 0;
    }
    internal static int LcTree(emon.Port.Cells lt, emon.Port.Cells ls, emon.Port.Cells gu, emon.Port.Cells ac, emon.Port.Cells tm, emon.Port.Cells rw, emon.Port.Cells cf, emon.Port.Cells lo, emon.Port.Cells pr, int page) {
        // The cut tree of the page's lines (SPEC 10.1.1 step 4), iteratively: a stack of regions in `ac`; the
        // horizontal cuts made are noted in `rw`.
        int n = emon.Port.CellsLen(ls);
        emon.Port.CellsDrop(ac, 0);
        emon.Port.CellsDrop(rw, 0);
        if (n == 0) {
            return 0;
        }
        LcPush(ac, 0, n, 0, -1);
        while (emon.Port.CellsLen(ac) > 0) {
            int top = emon.Port.CellsLen(ac) - 4;
            int a = emon.Port.CellsAt(ac, top);
            int b = emon.Port.CellsAt(ac, top + 1);
            int band = emon.Port.CellsAt(ac, top + 2);
            int pbot = emon.Port.CellsAt(ac, top + 3);
            emon.Port.CellsDrop(ac, top);
            LcRegion(lt, ls, gu, ac, tm, rw, cf, lo, pr, page, a, b, band, pbot);
        }
        return 0;
    }
    internal static int LcSideOf(emon.Port.Cells lt, int l, int bx1) {
        // 1 for a line right of the body block, 0 for one left of it.
        if (Evidence.LnGet(lt, l, Evidence.LhX0()) >= bx1) {
            return 1;
        }
        return 0;
    }
    internal static bool LcSideBefore(emon.Port.Cells lt, int a, int b, int bx1) {
        int sa = LcSideOf(lt, a, bx1);
        int sb = LcSideOf(lt, b, bx1);
        if (sa != sb) {
            return sa < sb;
        }
        return LcBefore(lt, a, b);
    }
    internal static int LcSortSide(emon.Port.Cells lt, emon.Port.Cells sd, int bx1) {
        int n = emon.Port.CellsLen(sd);
        int i = 1;
        int j = 0;
        int v = 0;
        int u = 0;
        int more = 1;
        while (i < n) {
            v = emon.Port.CellsAt(sd, i);
            j = i;
            more = 1;
            while ((j > 0) && (more == 1)) {
                u = emon.Port.CellsAt(sd, j - 1);
                if (LcSideBefore(lt, v, u, bx1)) {
                    emon.Port.CellsSet(sd, j, u);
                    j -= 1;
                } else {
                    more = 0;
                }
            }
            emon.Port.CellsSet(sd, j, v);
            i += 1;
        }
        return 0;
    }
    internal static int LcAssoc(emon.Port.Cells cf, int cf0, int nb, int y0, int y1) {
        // The body fragment (a row of `cf`) a side run lies beside: most overlap in y, the first on a tie; the
        // last one when none overlaps.
        int r = cf0;
        int best = (cf0 + nb) - 1;
        int bo = 0;
        while (r < (cf0 + nb)) {
            int ov = LcMin(y1, emon.Port.CellsAt(cf, (r * CfStride) + CfY1)) - LcMax(y0, emon.Port.CellsAt(cf, (r * CfStride) + CfY0));
            if (ov > bo) {
                bo = ov;
                best = r;
            }
            r += 1;
        }
        return best;
    }
    internal static int LcSideEmit(emon.Port.Cells wd, emon.Port.Cells lt, emon.Port.Cells sd, emon.Port.Cells lo, emon.Port.Cells cf, emon.Port.Cells pr, int page, int cf0, int nb) {
        // The side lines as fragments: per side, in rows, a run ends at a gap of more than 2 sizes. A run of at
        // most 4 lines, all in small type, is a margin note; any other is a sidebar. Each lies beside the body
        // fragment (`assoc`) it overlaps most, in its band.
        int n = emon.Port.CellsLen(sd);
        int dom = emon.Port.CellsAt(pr, PrDom);
        int bx1 = emon.Port.CellsAt(pr, PrBx1);
        int i = 0;
        int j = 0;
        int allsmall = 1;
        int x0 = 0;
        int y0 = 0;
        int x1 = 0;
        int y1 = 0;
        int role = 0;
        int @as = 0;
        int bandof = 0;
        int first = 0;
        LcSortSide(lt, sd, bx1);
        while (i < n) {
            j = i;
            allsmall = 1;
            int l0 = emon.Port.CellsAt(sd, i);
            x0 = Evidence.LnGet(lt, l0, Evidence.LhX0());
            y0 = Evidence.LnGet(lt, l0, Evidence.LhY0());
            x1 = Evidence.LnGet(lt, l0, Evidence.LhX1());
            y1 = Evidence.LnGet(lt, l0, Evidence.LhY1());
            first = emon.Port.CellsLen(lo);
            while ((j < n) && ((j == i) || ((LcSideOf(lt, emon.Port.CellsAt(sd, j), bx1) == LcSideOf(lt, emon.Port.CellsAt(sd, i), bx1)) && ((Evidence.LnGet(lt, emon.Port.CellsAt(sd, j), Evidence.LhY0()) - y1) <= (LcRunGap * dom))))) {
                int l = emon.Port.CellsAt(sd, j);
                x0 = LcMin(x0, Evidence.LnGet(lt, l, Evidence.LhX0()));
                y0 = LcMin(y0, Evidence.LnGet(lt, l, Evidence.LhY0()));
                x1 = LcMax(x1, Evidence.LnGet(lt, l, Evidence.LhX1()));
                y1 = LcMax(y1, Evidence.LnGet(lt, l, Evidence.LhY1()));
                if ((LcSize(wd, lt, l) * LcSmallDen) >= (dom * LcSmallNum)) {
                    allsmall = 0;
                }
                emon.Port.CellsPush(lo, l);
                j += 1;
            }
            role = Model.RlSidebar();
            if ((allsmall == 1) && ((j - i) <= LcNoteLines)) {
                role = Model.RlMargin();
            }
            @as = LcAssoc(cf, cf0, nb, y0, y1);
            bandof = 0;
            if (@as >= 0) {
                bandof = emon.Port.CellsAt(cf, (@as * CfStride) + CfBand);
            }
            emon.Port.CellsPush(cf, page);
            emon.Port.CellsPush(cf, bandof);
            emon.Port.CellsPush(cf, 1000 + LcSideOf(lt, emon.Port.CellsAt(sd, i), bx1));
            emon.Port.CellsPush(cf, role);
            emon.Port.CellsPush(cf, x0);
            emon.Port.CellsPush(cf, y0);
            emon.Port.CellsPush(cf, x1);
            emon.Port.CellsPush(cf, y1);
            emon.Port.CellsPush(cf, first);
            emon.Port.CellsPush(cf, j - i);
            emon.Port.CellsPush(cf, @as);
            emon.Port.CellsPush(cf, 0);
            emon.Port.CellsPush(cf, 0);
            i = j;
        }
        return 0;
    }
    internal static int LcBands(emon.Port.Cells cf, int r0, int r1, emon.Port.Cells rw) {
        // `band` of each body fragment: how many horizontal cuts lie above its middle and across its x-range (the
        // cuts of a part of the page count for the fragments of that part only), so the bands run top to bottom
        // whatever the order the tree made its cuts in.
        int nc = emon.Port.CellsLen(rw) / 3;
        int r = r0;
        int c = 0;
        int n = 0;
        while (r < r1) {
            int b = r * CfStride;
            int ym2 = emon.Port.CellsAt(cf, b + CfY0) + emon.Port.CellsAt(cf, b + CfY1);
            int fx0 = emon.Port.CellsAt(cf, b + CfX0);
            int fx1 = emon.Port.CellsAt(cf, b + CfX1);
            n = 0;
            c = 0;
            while (c < nc) {
                if (((2 * emon.Port.CellsAt(rw, c * 3)) <= ym2) && (emon.Port.CellsAt(rw, (c * 3) + 1) < fx1) && (emon.Port.CellsAt(rw, (c * 3) + 2) > fx0)) {
                    n += 1;
                }
                c += 1;
            }
            emon.Port.CellsSet(cf, b + CfBand, n);
            r += 1;
        }
        return 0;
    }
    internal static int LcNumber(emon.Port.Cells cf, int r0, int r1) {
        // `col`. A body fragment: how many body fragments of the page, before it, have its band. A side one (its
        // `col` is 1000 left of the body block, 1001 right of it, set by `lc-side-emit`): after the body fragments of
        // its band, the left strip before the right one; the notes of a side are ONE column.
        int r = r0;
        int q = 0;
        int c = 0;
        int nbody = 0;
        int hasleft = 0;
        while (r < r1) {
            if (emon.Port.CellsAt(cf, (r * CfStride) + CfRole) == Model.RlBody()) {
                c = 0;
                q = r0;
                while (q < r) {
                    if ((emon.Port.CellsAt(cf, (q * CfStride) + CfRole) == Model.RlBody()) && (emon.Port.CellsAt(cf, (q * CfStride) + CfBand) == emon.Port.CellsAt(cf, (r * CfStride) + CfBand))) {
                        c += 1;
                    }
                    q += 1;
                }
                emon.Port.CellsSet(cf, (r * CfStride) + CfCol, c);
            }
            r += 1;
        }
        r = r0;
        while (r < r1) {
            if (emon.Port.CellsAt(cf, (r * CfStride) + CfCol) == 1001) {
                nbody = 0;
                hasleft = 0;
                q = r0;
                while (q < r1) {
                    if (emon.Port.CellsAt(cf, (q * CfStride) + CfBand) == emon.Port.CellsAt(cf, (r * CfStride) + CfBand)) {
                        if (emon.Port.CellsAt(cf, (q * CfStride) + CfRole) == Model.RlBody()) {
                            nbody += 1;
                        }
                        if (emon.Port.CellsAt(cf, (q * CfStride) + CfCol) == 1000) {
                            hasleft = 1;
                        }
                    }
                    q += 1;
                }
                emon.Port.CellsSet(cf, (r * CfStride) + CfCol, nbody + hasleft);
            }
            r += 1;
        }
        r = r0;
        while (r < r1) {
            if (emon.Port.CellsAt(cf, (r * CfStride) + CfCol) == 1000) {
                nbody = 0;
                q = r0;
                while (q < r1) {
                    if ((emon.Port.CellsAt(cf, (q * CfStride) + CfBand) == emon.Port.CellsAt(cf, (r * CfStride) + CfBand)) && (emon.Port.CellsAt(cf, (q * CfStride) + CfRole) == Model.RlBody())) {
                        nbody += 1;
                    }
                    q += 1;
                }
                emon.Port.CellsSet(cf, (r * CfStride) + CfCol, nbody);
            }
            r += 1;
        }
        return 0;
    }
    public static int LcPage(emon.Port.Cells wd, emon.Port.Cells et, emon.Port.Cells lt, int page, emon.Port.Cells ls, emon.Port.Cells sd, emon.Port.Cells it, emon.Port.Cells io, emon.Port.Cells rw, emon.Port.Cells gu, emon.Port.Cells ac, emon.Port.Cells tm, emon.Port.Cells cf, emon.Port.Cells lo, emon.Port.Cells pr) {
        // One page. `ls` holds its upright lines' ids (rows of `lt`, sorted in rows by `lc-before`); fragments are
        // appended to `cf` (body ones first, then side) and their lines to `lo`. Answers the fragments written.
        int n = emon.Port.CellsLen(ls);
        int cf0 = emon.Port.CellsLen(cf) / CfStride;
        int i = 0;
        int dom = 0;
        int rtl = 0;
        int nb = 0;
        if (n == 0) {
            return 0;
        }
        emon.Port.CellsDrop(pr, 0);
        while (i < 16) {
            emon.Port.CellsPush(pr, 0);
            i += 1;
        }
        emon.Port.CellsSet(pr, PrForced, -1);
        dom = LcDom(wd, lt, ls, tm);
        emon.Port.CellsSet(pr, PrDom, dom);
        i = 0;
        while (i < n) {
            if (Evidence.LnGet(lt, emon.Port.CellsAt(ls, i), Evidence.LhDir()) == 1) {
                rtl += 1;
            }
            i += 1;
        }
        if ((rtl * 2) > n) {
            emon.Port.CellsSet(pr, PrRtl, 1);
        }
        LcSide(wd, et, lt, ls, sd, pr, dom);
        LcSweep(wd, lt, ls, dom, it, io, rw, gu, ac, tm);
        LcMerge(gu, dom);
        LcSortGu(gu);
        LcSplitAll(wd, lt, ls, gu);
        LcSortLines(lt, ls, 0, emon.Port.CellsLen(ls));
        LcExtendUp(wd, lt, ls, gu, dom);
        LcTree(lt, ls, gu, ac, tm, rw, cf, lo, pr, page);
        LcBands(cf, cf0, emon.Port.CellsLen(cf) / CfStride, rw);
        nb = (emon.Port.CellsLen(cf) / CfStride) - cf0;
        if (emon.Port.CellsLen(sd) > 0) {
            LcSideEmit(wd, lt, sd, lo, cf, pr, page, cf0, nb);
        }
        LcNumber(cf, cf0, emon.Port.CellsLen(cf) / CfStride);
        return (emon.Port.CellsLen(cf) / CfStride) - cf0;
    }
}
